SELECT fact FROM (
SELECT 'runtime' AS fact_kind,'' AS sort_id,JSON_OBJECT('kind','runtime','database',DATABASE(),'serverUuid',@@server_uuid,'mysqlVersion',@@version,'capturedAt',CAST(UTC_TIMESTAMP(6) AS CHAR),'tenantId','1','activeClaimCount',(SELECT COUNT(*) FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0),'counts',JSON_OBJECT('claim',(SELECT COUNT(*) FROM dcc_controlled_file_name_claim c WHERE c.id IN (SELECT c.id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)),'master',(SELECT COUNT(*) FROM dcc_controlled_file_master m WHERE m.id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)),'version',(SELECT COUNT(*) FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0))),'storage',(SELECT COUNT(*) FROM infra_file f WHERE f.id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0))) OR f.id IN (SELECT o.origin_source_file_id FROM dcc_controlled_file_source_ownership o WHERE o.controlled_file_id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)) OR o.source_file_id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0))))),'ownership',(SELECT COUNT(*) FROM dcc_controlled_file_source_ownership o WHERE o.controlled_file_id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)) OR o.source_file_id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)))),'ticket',(SELECT COUNT(*) FROM dcc_controlled_file_temporary_file t WHERE t.bound_controlled_file_id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)) OR t.storage_file_id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0))) OR t.storage_file_id IN (SELECT o.origin_source_file_id FROM dcc_controlled_file_source_ownership o WHERE o.controlled_file_id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)) OR o.source_file_id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0))))),'reference',(SELECT COUNT(*) FROM dcc_controlled_file r WHERE r.source_file_id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)))))) AS fact
UNION ALL
SELECT 'claim' AS fact_kind,CAST(c.id AS CHAR) AS sort_id,JSON_OBJECT('kind','claim','id',CAST(c.id AS CHAR),'tenantId',CAST(c.tenant_id AS CHAR),'masterId',CAST(c.master_id AS CHAR),'normalizedName',c.normalized_name,'nameHex',HEX(c.normalized_name),'deleted',(c.deleted+0),'activeFlag',(c.active_unique_flag+0)) AS fact FROM dcc_controlled_file_name_claim c WHERE c.id IN (SELECT c.id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)
UNION ALL
SELECT 'master' AS fact_kind,CAST(m.id AS CHAR) AS sort_id,JSON_OBJECT('kind','master','id',CAST(m.id AS CHAR),'tenantId',CAST(m.tenant_id AS CHAR),'fileName',m.file_name,'projectId',CAST(m.dcc_project_code_id AS CHAR),'leafId',CAST(m.file_type_taxonomy_leaf_id AS CHAR),'normalizedNumber',m.normalized_file_number,'fileNumber',m.file_number,'currentActiveFileId',CAST(m.current_active_controlled_file_id AS CHAR),'status',m.status,'deleted',(m.deleted+0)) AS fact FROM dcc_controlled_file_master m WHERE m.id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)
UNION ALL
SELECT 'version' AS fact_kind,CAST(v.id AS CHAR) AS sort_id,JSON_OBJECT('kind','version','id',CAST(v.id AS CHAR),'tenantId',CAST(v.tenant_id AS CHAR),'masterId',CAST(v.master_id AS CHAR),'sourceFileId',CAST(v.source_file_id AS CHAR),'originalFileId',CAST(v.original_file_id AS CHAR),'sourceSha256',v.source_sha256,'projectId',CAST(v.dcc_project_code_id AS CHAR),'leafId',CAST(v.file_type_taxonomy_id AS CHAR),'fileNumber',v.file_number,'versionNo',v.version_no,'status',v.status,'processInstanceId',CAST(v.process_instance_id AS CHAR),'predecessorId',CAST(v.predecessor_controlled_file_id AS CHAR),'deleted',(v.deleted+0)) AS fact FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0))
UNION ALL
SELECT 'storage' AS fact_kind,CAST(f.id AS CHAR) AS sort_id,JSON_OBJECT('kind','storage','id',CAST(f.id AS CHAR),'configId',CAST(f.config_id AS CHAR),'name',f.name,'nameHex',HEX(f.name),'mime',f.type,'size',CAST(f.size AS CHAR),'deleted',(f.deleted+0)) AS fact FROM infra_file f WHERE f.id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0))) OR f.id IN (SELECT o.origin_source_file_id FROM dcc_controlled_file_source_ownership o WHERE o.controlled_file_id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)) OR o.source_file_id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0))))
UNION ALL
SELECT 'ownership' AS fact_kind,CAST(o.id AS CHAR) AS sort_id,JSON_OBJECT('kind','ownership','id',CAST(o.id AS CHAR),'tenantId',CAST(o.tenant_id AS CHAR),'controlledFileId',CAST(o.controlled_file_id AS CHAR),'sourceFileId',CAST(o.source_file_id AS CHAR),'originSourceFileId',CAST(o.origin_source_file_id AS CHAR),'sourceSha256',o.source_sha256,'ownershipType',o.ownership_type,'deleted',(o.deleted+0)) AS fact FROM dcc_controlled_file_source_ownership o WHERE o.controlled_file_id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)) OR o.source_file_id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)))
UNION ALL
SELECT 'ticket' AS fact_kind,CAST(t.id AS CHAR) AS sort_id,JSON_OBJECT('kind','ticket','id',CAST(t.id AS CHAR),'tenantId',CAST(t.tenant_id AS CHAR),'controlledFileId',CAST(t.bound_controlled_file_id AS CHAR),'storageFileId',CAST(t.storage_file_id AS CHAR),'originalName',t.original_file_name,'nameHex',HEX(t.original_file_name),'fileSha256',t.file_sha256,'size',CAST(t.file_size AS CHAR),'purpose',t.purpose,'status',t.status,'cleanupStatus',t.cleanup_status,'deleted',(t.deleted+0)) AS fact FROM dcc_controlled_file_temporary_file t WHERE t.bound_controlled_file_id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)) OR t.storage_file_id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0))) OR t.storage_file_id IN (SELECT o.origin_source_file_id FROM dcc_controlled_file_source_ownership o WHERE o.controlled_file_id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)) OR o.source_file_id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0))))
UNION ALL
SELECT 'reference' AS fact_kind,CAST(r.id AS CHAR) AS sort_id,JSON_OBJECT('kind','reference','id',CAST(r.id AS CHAR),'tenantId',CAST(r.tenant_id AS CHAR),'masterId',CAST(r.master_id AS CHAR),'sourceFileId',CAST(r.source_file_id AS CHAR),'sourceSha256',r.source_sha256,'deleted',(r.deleted+0)) AS fact FROM dcc_controlled_file r WHERE r.source_file_id IN (SELECT v.source_file_id FROM dcc_controlled_file v WHERE v.id IN (SELECT v.id FROM dcc_controlled_file v WHERE v.master_id IN (SELECT c.master_id FROM dcc_controlled_file_name_claim c WHERE c.tenant_id=1 AND c.deleted=0)))
) captured_facts ORDER BY fact_kind,sort_id;
